const DEFAULT_LANG = 'tr';
const LANG_KEY = 'benchcompass-lang';

let currentLang = DEFAULT_LANG;
if (typeof window !== 'undefined' && typeof window.localStorage !== 'undefined') {
  const stored = window.localStorage.getItem(LANG_KEY);
  if (stored && translations[stored]) currentLang = stored;
}

/**
 * Anahtar-bazlı çeviri. Bilinmeyen anahtar TR'ye düşer; TR'de de yoksa
 * anahtarın kendisi döner. {var} yer tutucuları vars ile doldurulur.
 */
function t(key, vars = {}) {
  const dict = translations[currentLang] || translations[DEFAULT_LANG];
  let s = dict[key] ?? translations[DEFAULT_LANG][key] ?? key;
  Object.keys(vars).forEach((k) => {
    s = String(s).replaceAll('{' + k + '}', String(vars[k]));
  });
  return s;
}

/** Dili değiştirir, localStorage'a yazar, <html lang> günceller. */
function setLang(lang) {
  if (!translations[lang]) return currentLang;
  currentLang = lang;
  if (typeof window !== 'undefined') {
    if (typeof window.localStorage !== 'undefined') {
      window.localStorage.setItem(LANG_KEY, lang);
    }
    if (window.document && window.document.documentElement) {
      window.document.documentElement.setAttribute('lang', lang);
    }
  }
  return currentLang;
}

/** Aktif dil kodunu döner ('tr' | 'en'). */
function getLang() {
  return currentLang;
}

function toggleLang() {
  return setLang(currentLang === 'tr' ? 'en' : 'tr');
}

// --- Tier etiketleri (canonical değer → çeviri anahtarı) -------------------
// computeTier / api/compat.py canonical Türkçe değerler döndürür (G8 mirror).
// Görüntü katmanı bu map üzerinden t('tier.*') ile çevirir — mantık/test kırılmaz.
// Backend ASCII varyantları ("Sinirda"/"Degil") de eşlenir.
const TIER_TO_KEY = {
  'Tam Uyumlu': 'tier.full',
  'Uyumlu (Sınırda)': 'tier.border',
  'Uyumlu (Sinirda)': 'tier.border',
  'Dikkatli Kullan': 'tier.caution',
  'Uygun Değil': 'tier.notfit',
  'Uygun Degil': 'tier.notfit',
};

/** Canonical tier değerini görüntü dilinde döndürür. */
function tierT(tier) {
  const key = TIER_TO_KEY[tier];
  return key ? t(key) : (tier || '');
}

/** Canonical tier değerinin kısa etiketini (TAM/SINIR/DIKKAT/UYGUN) döndürür. */
function tierShortT(tier) {
  const key = TIER_TO_KEY[tier];
  return key ? t(key.replace('tier.', 'tier.short.')) : (tier || '');
}

// Node.js / Vitest test ortamı için export wrapper (app.js deseniyle uyumlu)
if (typeof globalThis !== 'undefined') {
  globalThis.t = t;
  globalThis.setLang = setLang;
  globalThis.getLang = getLang;
  globalThis.toggleLang = toggleLang;
  globalThis.tierT = tierT;
  globalThis.tierShortT = tierShortT;
  globalThis.__translations = translations;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    t,
    setLang,
    getLang,
    toggleLang,
    tierT,
    tierShortT,
    translations,
    DEFAULT_LANG,
    LANG_KEY,
  };
}

// Global scope'a koy (index.html Alpine şablonlarından erişir)
if (typeof window !== 'undefined') {
  window.t = t;
  window.setLang = setLang;
  window.getLang = getLang;
  window.toggleLang = toggleLang;
  window.tierT = tierT;
  window.tierShortT = tierShortT;
}
